16	constexpr size_t kSha256Size = 32;
17	constexpr std::string_view kDigestPrefix = "sha256:";
18	constexpr size_t kDigestHexLen = 2 * kSha256Size;  // 64 lowercase hex chars
19	constexpr std::string_view kSpkiFingerprintPrefix = "spki-sha256:";
20	
21	constexpr std::string_view kPemBegin = "-----BEGIN PUBLIC KEY-----";
22	constexpr std::string_view kPemEnd = "-----END PUBLIC KEY-----";
