32	// ASCII whitespace permitted around the PEM block: the standard C/POSIX set
33	// of horizontal tab, LF, vertical tab, form feed, CR and space (the bytes for
34	// which Python's bytes.isspace() is true within ASCII). Everything else --
35	// including non-ASCII bytes -- is significant content and causes rejection.
36	bool isAsciiSpace(unsigned char c) {
37	    return c == ' ' || (c >= '\t' && c <= '\r');
38	}
39	
40	bool isBase64Char(char c) {
41	    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
42	           (c >= '0' && c <= '9') || c == '+' || c == '/' || c == '=';
43	}
44	
45	int base64Value(char c) {
46	    if (c >= 'A' && c <= 'Z') return c - 'A';
47	    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
48	    if (c >= '0' && c <= '9') return c - '0' + 52;
49	    if (c == '+') return 62;
50	    if (c == '/') return 63;
51	    return -1;
52	}
53	
54	// Strict canonical base64 decoder: length must be a positive multiple of
55	// four, '=' may occur only in the final quantum and only as the conventional
56	// "x=" / "xx==" tail, every other character must be alphabet data. OpenSSL's
57	// streaming decoder is noticeably lenient, so this is implemented on purpose
58	// to make truncated or corrupted encodings fail deterministically.
59	bool decodeBase64(const std::string& in, std::vector<unsigned char>& out) {
60	    if (in.empty() || in.size() % 4 != 0) {
61	        return false;
62	    }
63	    out.clear();
64	    out.reserve((in.size() / 4) * 3);
65	
66	    const size_t quanta = in.size() / 4;
67	    for (size_t q = 0; q < quanta; ++q) {
68	        const size_t i = 4 * q;
69	        const bool last = (q == quanta - 1);
70	        const int a = base64Value(in[i]);
71	        const int b = base64Value(in[i + 1]);
72	        if (a < 0 || b < 0) {
73	            return false;
74	        }
75	
76	        const bool pad2 = in[i + 2] == '=';
77	        const bool pad3 = in[i + 3] == '=';
78	        if (!last && (pad2 || pad3)) {
79	            return false;  // padding anywhere before the final quantum
80	        }
81	
82	        if (pad2) {
83	            if (!pad3) {
84	                return false;  // '=' at position 2 requires one at position 3
85	            }
86	            if ((b & 0x0f) != 0) {
87	                return false;  // non-canonical: unused padding bits must be 0
88	            }
89	            out.push_back(static_cast<unsigned char>((a << 2) | (b >> 4)));
90	        } else {
91	            const int c = base64Value(in[i + 2]);
92	            if (c < 0) {
93	                return false;
94	            }
95	            if (pad3) {
96	                if ((c & 0x03) != 0) {
97	                    return false;  // non-canonical: unused padding bits must be 0
98	                }
99	                out.push_back(static_cast<unsigned char>((a << 2) | (b >> 4)));
100	                out.push_back(
101	                    static_cast<unsigned char>(((b & 0x0f) << 4) | (c >> 2)));
102	            } else {
103	                const int d = base64Value(in[i + 3]);
104	                if (d < 0) {
105	                    return false;
106	                }
107	                out.push_back(static_cast<unsigned char>((a << 2) | (b >> 4)));
108	                out.push_back(
109	                    static_cast<unsigned char>(((b & 0x0f) << 4) | (c >> 2)));
110	                out.push_back(
111	                    static_cast<unsigned char>(((c & 0x03) << 6) | d));
112	            }
113	        }
114	    }
115	    return true;
116	}
117	
118	std::string_view stripOneCr(std::string_view line) {
119	    if (!line.empty() && line.back() == '\r') {
120	        line.remove_suffix(1);
121	    }
122	    return line;
123	}
124	
125	// Parses the strict single-block PEM structure:
126	//
127	//   [ASCII ws] -----BEGIN PUBLIC KEY----- LF/CRLF
128	//   (base64 lines; no blank or whitespace-only lines) ...
129	//   -----END PUBLIC KEY----- LF/CRLF
130	//   [ASCII ws]
131	//
132	// Anything else is rejected: non-whitespace outside the block, more than one
133	// block, any other PEM label (private keys, certificates, PKCS#1 RSA public
134	// keys, ...), malformed or truncated base64. Returns the decoded payload
135	// (nominally DER SubjectPublicKeyInfo) on success; structural DER validation
136	// happens in the caller.
137	bool parsePublicPem(const std::vector<unsigned char>& raw,
138	                    std::vector<unsigned char>& payloadOut) {
139	    const size_t n = raw.size();
140	
141	    // Preamble: only ASCII whitespace may precede the block.
142	    size_t pos = 0;
143	    while (pos < n && isAsciiSpace(raw[pos])) {
144	        ++pos;
145	    }
146	    if (pos == n) {
147	        return false;  // empty or whitespace-only file
148	    }
149	
150	    auto takeLine = [&](size_t start,
151	                        std::string_view& line) -> size_t {
152	        size_t end = start;
153	        while (end < n && raw[end] != '\n') {
154	            ++end;
155	        }
156	        line = std::string_view(
157	            reinterpret_cast<const char*>(raw.data() + start), end - start);
158	        return (end < n) ? end + 1 : end;
159	    };
160	
161	    std::string_view line;
162	    pos = takeLine(pos, line);
163	    // Exactly the BEGIN marker, optionally followed by a single CR (CRLF).
164	    if (stripOneCr(line) != kPemBegin) {
165	        return false;
166	    }
167	
168	    std::string base64;
169	    bool sawEnd = false;
170	
171	    while (pos < n) {
172	        pos = takeLine(pos, line);
173	        const std::string_view core = stripOneCr(line);
174	
175	        if (core == kPemEnd) {
176	            sawEnd = true;
177	            break;
178	        }
179	
180	        if (core.empty()) {
181	            return false;  // no blank lines inside the block
182	        }
183	        bool onlySpace = true;
184	        for (char c : core) {
185	            if (!isAsciiSpace(static_cast<unsigned char>(c))) {
186	                onlySpace = false;
187	                break;
188	            }
189	        }
190	        if (onlySpace) {
191	            return false;  // whitespace is allowed only around the block
192	        }
193	
194	        // A payload line must be pure base64. '-' is deliberately not in the
195	        // alphabet, so any other PEM boundary (a second block, a certificate
196	        // or private-key label) fails here rather than being consumed.
197	        for (char c : core) {
198	            if (!isBase64Char(c)) {
199	                return false;
200	            }
201	        }
202	        base64.append(core);
203	    }
204	
205	    if (!sawEnd) {
206	        return false;  // truncated: no END line
207	    }
208	
209	    // Nothing but ASCII whitespace may follow the block through EOF, so a
210	    // second key or any appended text is rejected instead of ignored.
211	    while (pos < n) {
212	        if (!isAsciiSpace(raw[pos])) {
213	            return false;
214	        }
215	        ++pos;
216	    }
217	
218	    return decodeBase64(base64, payloadOut) && !payloadOut.empty();
219	}
220	
221	// Validates that the decoded payload is one complete SubjectPublicKeyInfo DER
222	// structure covering every byte, understood by the crypto library, and in
223	// canonical encoding. Re-encoding the parsed structure must reproduce the
224	// payload byte for byte; that round trip rules out non-DER BER encodings and
225	// other representations OpenSSL might otherwise accept. The bytes hashed for
226	// the fingerprint are therefore the canonical SPKI DER, so PEM line wrapping
227	// and line endings never influence the result.
228	bool extractSpkiDer(const std::vector<unsigned char>& rawBytes,
229	                    std::vector<unsigned char>& derOut) {
230	    std::vector<unsigned char> payload;
231	    if (!parsePublicPem(rawBytes, payload)) {
232	        return false;
233	    }
234	
235	    const unsigned char* p = payload.data();
236	    const std::unique_ptr<EVP_PKEY, decltype(&EVP_PKEY_free)> pkey(
237	        d2i_PUBKEY_ex(nullptr, &p, static_cast<long>(payload.size()), nullptr,
238	                      nullptr),
239	        &EVP_PKEY_free);
240	    if (!pkey) {
241	        return false;
242	    }
243	    if (p - payload.data() != static_cast<ptrdiff_t>(payload.size())) {
244	        return false;  // trailing bytes after the SPKI structure
245	    }
246	
247	    const int encLen = i2d_PUBKEY(pkey.get(), nullptr);
248	    if (encLen <= 0 ||
249	        static_cast<size_t>(encLen) != payload.size()) {
250	        return false;
251	    }
252	    std::vector<unsigned char> reencoded(static_cast<size_t>(encLen));
253	    unsigned char* q = reencoded.data();
254	    if (i2d_PUBKEY(pkey.get(), &q) != encLen || reencoded != payload) {
255	        return false;  // non-canonical DER
256	    }
257	
258	    derOut = std::move(payload);
259	    return true;
260	}
261	
262	// --- Shared regular-file reading ------------------------------------------
263	//
264	// digest, verify-digest and key-id all walk the same pipeline: require a
265	// regular file, open it, then read its complete raw bytes from the start in
266	// fixed-size passes until normal EOF, treating text and binary content
267	// identically. The three only differ in what happens to each chunk, which is
268	// expressed by a ByteSink (see processFileChunks):
269	//   * digest / verify-digest stream the bytes straight into SHA-256, so their
270	//     memory use does not grow with the file;
271	//   * key-id collects them, because parsing a PEM public key fundamentally
272	//     needs the whole file (public keys are small).
273	// The error reporting for the access, open and read stages lives here once;
274	// sinks report only their own processing failures.
275	
276	// Size of every read pass for all three commands.
277	constexpr size_t kReadChunkSize = 64 * 1024;
278	
279	// Requires pathArg to name an existing regular file and opens it for raw
280	// binary reads. The two pre-read failure stages stay distinct: a failure to
281	// stat/access the path ("cannot access", covering a missing path) and an
282	// object that is not a regular file, followed by a failure to open it
283	// ("cannot open"). On failure prints a reason containing pathArg to stderr.
284	bool openRegularInput(const char* pathArg, std::ifstream& in) {
285	    namespace fs = std::filesystem;
286	    const fs::path path(pathArg);
287	
288	    std::error_code ec;
289	    if (!fs::is_regular_file(path, ec)) {
290	        if (ec) {
291	            std::cerr << "sealmark: cannot access '" << pathArg << "': "
292	                      << ec.message() << '\n';
293	        } else {
294	            std::cerr << "sealmark: '" << pathArg
295	                      << "' is not a regular file\n";
296	        }
297	        return false;
298	    }
299	
300	    errno = 0;
301	    in.open(path, std::ios::binary);
302	    if (!in) {
303	        const int err = errno;
304	        std::cerr << "sealmark: cannot open '" << pathArg << "': "
305	                  << (err != 0 ? std::strerror(err) : "open failed") << '\n';
306	        return false;
307	    }
308	    return true;
309	}
310	
311	// Feeds a regular file's complete raw bytes to sink:
312	//   start()             once, immediately after the file is opened;
313	//   consume(data, size) for every non-empty chunk, including a final short
314	//                       one (a zero-length file yields no consume() call);
315	//   finish()            exactly once, only after a read reaching normal EOF.
316	// A false return aborts the operation and the sink is responsible for its own
317	// diagnostic. A final read shorter than the chunk -- including zero bytes on
318	// an empty file -- after a non-failed read is normal EOF; only a failed read
319	// (badbit) after some bytes were delivered is a read error, which is reported
320	// as such and never reaches finish(). Hence a mid-read failure can never
321	// surface as a digest, a match/mismatch result or a key fingerprint.
322	template <typename ByteSink>
323	bool processFileChunks(const char* pathArg, ByteSink& sink) {
324	    std::ifstream in;
325	    if (!openRegularInput(pathArg, in)) {
326	        return false;
327	    }
328	    if (!sink.start()) {
329	        return false;
330	    }
331	
332	    std::vector<char> buffer(kReadChunkSize);
333	    while (true) {
334	        in.read(buffer.data(), static_cast<std::streamsize>(buffer.size()));
335	        const std::streamsize got = in.gcount();
336	        if (got > 0 &&
337	            !sink.consume(buffer.data(), static_cast<size_t>(got))) {
338	            return false;
339	        }
340	        if (in.bad()) {
341	            // The file was already opened successfully; this is a read-stage
342	            // failure, never an open error or a content/format problem.
343	            std::cerr << "sealmark: failed to read '" << pathArg << "'\n";
344	            return false;
345	        }
346	        if (got < static_cast<std::streamsize>(buffer.size())) {
347	            break;  // normal end of file: a short or empty final read
348	        }
349	    }
350	
351	    return sink.finish();
352	}
353	
354	// Streams every chunk through SHA-256 with fixed-size buffers, so memory use
355	// stays constant regardless of file size. On a processing failure it prints
356	// the reason (including pathArg) itself; after success hash() holds exactly
357	// kSha256Size bytes.
358	class Sha256StreamSink {
359	public:
360	    explicit Sha256StreamSink(const char* pathArg) : pathArg_(pathArg) {}
361	
362	    bool start() {
363	        ctx_.reset(EVP_MD_CTX_new());
364	        if (!ctx_ ||
365	            EVP_DigestInit_ex(ctx_.get(), EVP_sha256(), nullptr) != 1) {
366	            fail("SHA-256 initialization failed");
367	            return false;
368	        }
369	        return true;
370	    }
371	
372	    bool consume(const char* data, size_t size) {
373	        if (EVP_DigestUpdate(ctx_.get(), data, size) != 1) {
374	            fail("SHA-256 computation failed");
375	            return false;
376	        }
377	        return true;
378	    }
379	
380	    bool finish() {
381	        unsigned int hashLen = 0;
382	        if (EVP_DigestFinal_ex(ctx_.get(), hash_, &hashLen) != 1 ||
383	            hashLen != kSha256Size) {
384	            fail("SHA-256 computation failed");
385	            return false;
386	        }
387	        return true;
388	    }
389	
390	    const unsigned char* hash() const { return hash_; }
391	
392	private:
393	    void fail(const char* what) {
394	        std::cerr << "sealmark: " << what << " for '" << pathArg_ << "'\n";
395	    }
396	
397	    const char* pathArg_;
398	    std::unique_ptr<EVP_MD_CTX, decltype(&EVP_MD_CTX_free)> ctx_{
399	        nullptr, &EVP_MD_CTX_free};
400	    unsigned char hash_[kSha256Size] = {};
401	};
402	
403	// Collects every chunk into one byte buffer. Used by key-id, which needs the
404	// complete file contents before it can parse and validate the public key.
405	class CollectAllSink {
406	public:
407	    bool start() { return true; }
408	
409	    bool consume(const char* data, size_t size) {
410	        const auto* begin = reinterpret_cast<const unsigned char*>(data);
411	        bytes_.insert(bytes_.end(), begin, begin + size);
412	        return true;
413	    }
414	
415	    bool finish() { return true; }
416	
417	    std::vector<unsigned char>& bytes() { return bytes_; }
418	
419	private:
420	    std::vector<unsigned char> bytes_;
421	};
422	
423	// Renders bytes as lowercase hexadecimal with no separators or prefix.
424	std::string toHexLower(const unsigned char* data, size_t size) {
425	    static constexpr char kHex[] = "0123456789abcdef";
426	    std::string out;
427	    out.reserve(2 * size);
428	    for (size_t i = 0; i < size; ++i) {
429	        out.push_back(kHex[data[i] >> 4]);
430	        out.push_back(kHex[data[i] & 0x0f]);
431	    }
432	    return out;
433	}
434	
435	int digestFile(const char* pathArg) {
436	    Sha256StreamSink sink(pathArg);
437	    if (!processFileChunks(pathArg, sink)) {
438	        return 1;
439	    }
440	
441	    std::cout << kDigestPrefix
442	              << toHexLower(sink.hash(), kSha256Size) << '\n';
443	    return 0;
444	}
445	
446	// Accepts only "sha256:" followed by exactly 64 lowercase hexadecimal
447	// characters: no missing prefix, no uppercase, no other algorithm names,
448	// no surrounding whitespace or trailing content.
449	bool isValidExpectedDigest(std::string_view digest) {
450	    if (digest.size() != kDigestPrefix.size() + kDigestHexLen) {
451	        return false;
452	    }
453	    if (digest.substr(0, kDigestPrefix.size()) != kDigestPrefix) {
454	        return false;
455	    }
456	    for (size_t i = kDigestPrefix.size(); i < digest.size(); ++i) {
457	        const char c = digest[i];
458	        const bool isHex =
459	            (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f');
460	        if (!isHex) {
461	            return false;
462	        }
463	    }
464	    return true;
465	}
466	
467	int verifyDigestFile(const char* pathArg, std::string_view expected) {
468	    Sha256StreamSink sink(pathArg);
469	    if (!processFileChunks(pathArg, sink)) {
470	        return 1;
471	    }
472	
473	    std::string actual;
474	    actual.reserve(kDigestPrefix.size() + kDigestHexLen);
475	    actual.append(kDigestPrefix);
476	    actual.append(toHexLower(sink.hash(), kSha256Size));
477	
478	    if (actual == expected) {
479	        std::cout << "match\n";
480	        return 0;
481	    }
482	    std::cout << "mismatch\n";
483	    return 3;
484	}
485	
486	int keyIdFile(const char* pathArg) {
487	    CollectAllSink sink;
488	    if (!processFileChunks(pathArg, sink)) {
489	        return 1;
490	    }
491	
492	    std::vector<unsigned char> spkiDer;
493	    if (!extractSpkiDer(sink.bytes(), spkiDer)) {
494	        std::cerr << "sealmark: '" << pathArg
495	                  << "' does not contain a single valid PEM-encoded "
496	                     "SubjectPublicKeyInfo public key (PUBLIC KEY)\n";
497	        return 1;
498	    }
499	
500	    unsigned char hash[kSha256Size];
501	    unsigned int hashLen = 0;
502	    if (EVP_Digest(spkiDer.data(), spkiDer.size(), hash, &hashLen,
503	                   EVP_sha256(), nullptr) != 1 ||
504	        hashLen != kSha256Size) {
505	        std::cerr << "sealmark: SHA-256 computation failed for '" << pathArg
506	                  << "'\n";
507	        return 1;
508	    }
509	
510	    std::cout << kSpkiFingerprintPrefix
511	              << toHexLower(hash, kSha256Size) << '\n';
512	    return 0;
513	}
514	
515	}  // namespace
516	
517	int main(int argc, char* argv[]) {
518	    if (argc == 2 && std::string_view(argv[1]) == "--version") {
519	        std::cout << "sealmark 0.1.0\n";
520	        return 0;
521	    }
522	    if (argc == 3 && std::string_view(argv[1]) == "digest") {
523	        if (argv[2][0] == '\0') {
524	            return printUsage();
525	        }
526	        return digestFile(argv[2]);
527	    }
528	    if (argc == 3 && std::string_view(argv[1]) == "key-id") {
529	        if (argv[2][0] == '\0') {
530	            return printUsage();
531	        }
532	        return keyIdFile(argv[2]);
533	    }
534	    if (argc == 4 && std::string_view(argv[1]) == "verify-digest") {
535	        // Validate every argument before touching the file so that a bad
536	        // path and a malformed digest together still report a usage error.
537	        if (argv[2][0] == '\0' || !isValidExpectedDigest(argv[3])) {
538	            return printUsage();
539	        }
540	        return verifyDigestFile(argv[2], argv[3]);
541	    }
542	    return printUsage();
543	}
