    bool sawEnd = false;

    while (pos < n) {
        pos = takeLine(pos, line);
        const std::string_view core = stripOneCr(line);

        if (core == kPemEnd) {
            sawEnd = true;
            break;
        }

        if (core.empty()) {
            return false;  // no blank lines inside the block
