    der = rng.choice(DERS)
    enc = base64.b64encode(der)
    width = rng.choice([1, 2, 3, 4, 5, 7, 16, 64, 73, len(enc)])
    nl = rng.choice([b"\n", b"\r\n"])
    lines = [enc[i:i + width] for i in range(0, len(enc), width)]
    out = BEGIN + nl + nl.join(lines) + nl + END
    if rng.random() < 0.8:
        out += nl
    if rng.random() < 0.6:
        out = WS * rng.randint(0, 6) + out
    if rng.random() < 0.6:
        out = out + WS * rng.randint(0, 6)
    return out


def mutate(rng, data):
    b = bytearray(data)
    for _ in range(rng.randint(1, 3)):
        k = rng.randrange(0, len(b) + 1)
        op = rng.randrange(4)
        if op == 0 and b and k < len(b):
            del b[k:k + rng.randrange(1, min(4, len(b) - k) + 1)]
