            b[k:k] = bytes([rng.randrange(256)])
        elif op == 2 and b:
            b[min(k, len(b) - 1)] = rng.randrange(256)
        else:
            b[k:k] = rng.choice([
                b"=", b"\n", b"\r", b"-", b" ",
                b"-----END PUBLIC KEY-----", b"BEGIN", b"\xff",
